<script setup>
import { ref, computed, watch } from 'vue'
import Button from 'primevue/button'
import Textarea from 'primevue/textarea'
import Select from 'primevue/select'
import { MessageSquare, ListTodo, Check, RotateCcw } from 'lucide-vue-next'
import { workspace } from '../../stores/workspace'
import { projects } from '../../stores/projects'
import { session } from '../../stores/session'
import { api } from '../../services/api'
import { initials, timestamp, calendar } from '../../utils/format'
const props=defineProps({selection:Object,taskId:Number,tab:String}),emit=defineEmits(['tab','task'])
const text=ref(''),busy=ref(false),error=ref(''),resolved=ref(false)
const task=computed(()=>workspace.state.detail?.tasks.find(t=>t.id===props.taskId) || workspace.state.detail?.tasks[0])
const comments=computed(()=>workspace.state.detail?.comments.filter(c=>resolved.value || !c.resolved) || [])
const canResolve=c=>c.author.id===session.state.user.id || session.state.team.role==='LEADER' || ['EDIT','FULL_ACCESS'].includes(workspace.state.active.permission)
watch(()=>workspace.state.active?.id,()=>{text.value='';error.value=''})
async function post(){if(busy.value||!text.value.trim())return;busy.value=true;error.value='';try{await api.post(`/workspace/nodes/${workspace.state.active.id}/comments`,{content:text.value,...props.selection,version:workspace.state.version,task_id:task.value?.id || null});text.value='';await workspace.refresh()}catch(e){error.value=e.friendly}finally{busy.value=false}}
async function resolve(comment){busy.value=true;try{await api.patch(`/workspace/comments/${comment.id}`,{resolved:!comment.resolved});await workspace.refresh()}catch(e){error.value=e.friendly}finally{busy.value=false}}
</script>
<template><section class="workspace-context"><div class="context-tabs"><button :class="{active:tab==='comments'}" @click="$emit('tab','comments')"><MessageSquare :size="14"/> Discussion</button><button :class="{active:tab==='task'}" @click="$emit('tab','task')"><ListTodo :size="14"/> Task context</button></div><div v-if="tab==='task'" class="context-body"><Select v-if="workspace.state.detail?.tasks.length>1" :modelValue="task?.id" :options="workspace.state.detail.tasks" optionLabel="title" optionValue="id" aria-label="Related task" @update:modelValue="$emit('task',$event)"/><template v-if="task"><span class="eyebrow">TF-{{ task.id }} · {{ task.priority }}</span><h3>{{ task.title }}</h3><p class="field-hint">{{ task.assignee?.name || 'Unassigned' }}</p><dl class="task-context-facts"><div><dt>Status</dt><dd>{{ task.status.replaceAll('_',' ').toLowerCase() }}</dd></div><div><dt>Progress</dt><dd>{{ task.progress }}%</dd></div><div><dt>Deadline</dt><dd>{{ calendar(task.deadline) }}</dd></div></dl><div class="progress-track mb-3"><span :style="{width:`${task.progress}%`}"></span></div><Button label="Open task details" severity="secondary" size="small" @click="projects.openTask(task.id)"/></template><div v-else class="compact-empty">No task is linked to this file. Leaders can add related files from task details.</div></div><div v-else class="context-body"><div class="discussion-heading"><h3>Code discussion</h3><button class="text-button" @click="resolved=!resolved">{{ resolved?'Hide resolved':'Show resolved' }}</button></div><p class="field-hint">Comments anchor to saved file lines and versions. Select a line in the editor or click a gutter marker.</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><article v-for="comment in comments" :key="comment.id" :class="['code-comment',{resolved:comment.resolved}]"><div class="comment-meta"><strong>{{ comment.author.name }}</strong><span>{{ comment.resolved?'Resolved':'Open' }}</span></div><span class="code-anchor">Line {{ comment.line_start }}{{ comment.line_end!==comment.line_start?`–${comment.line_end}`:'' }} · version {{ comment.file_version }}</span><p>{{ comment.content }}</p><footer><time>{{ timestamp(comment.created_at) }}</time><button v-if="canResolve(comment)" class="text-button" :disabled="busy" @click="resolve(comment)"><component :is="comment.resolved?RotateCcw:Check" :size="12"/>{{ comment.resolved?'Reopen':'Resolve' }}</button></footer></article><div v-if="!comments.length" class="compact-empty">No open discussions. Bring context to the code.</div><form v-if="workspace.state.active?.kind==='file' && !workspace.state.active.binary" class="form-stack code-composer" @submit.prevent="post"><label for="code-comment">Comment on line {{ selection.line_start }}{{ selection.line_end!==selection.line_start?`–${selection.line_end}`:'' }}</label><Textarea id="code-comment" v-model="text" rows="3" maxlength="5000" required :disabled="busy || workspace.dirty.value" placeholder="Discuss this saved line…"/><p v-if="workspace.dirty.value" class="field-hint">Save your draft before adding a line comment.</p><Button type="submit" label="Add code comment" :loading="busy" :disabled="!text.trim() || workspace.dirty.value"/></form></div></section></template>
